package com.ianblk.zianmobs.client;
import com.google.gson.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.Screenshot;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.gui.components.Button;
import java.nio.file.*;
/** Real server-generated Manager and Mobs snapshots; optional jar only in the isolated client. */
public final class ConsolidationClientSmoke {
 private static int stage=-1,ticks,checks;
 static void register(){if("true".equals(System.getenv("ZIAN_CONSOLIDATION_CLIENT")))net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener((net.neoforged.neoforge.client.event.ClientTickEvent.Post e)->tick());}
 private static void require(boolean b,String text){if(!b)throw new IllegalStateException(text);checks++;}
 private static void tick(){var mc=Minecraft.getInstance();if(mc.screen==null||mc.getOverlay()!=null)return;try{if(stage<0){require(mc.gameDirectory.toPath().toAbsolutePath().toString().contains("consolidation-client-smoke"),"isolated profile");stage=0;mc.options.pauseOnLostFocus=false;open(mc);return;}if(++ticks<25)return;ticks=0;require((int)mc.getWindow().getGuiScale()==2+stage/6,"GUI scale");Screenshot.grab(mc.gameDirectory,"consolidation-"+stage+".png",mc.getMainRenderTarget(),c->{});if(++stage<18)open(mc);else{Files.writeString(mc.gameDirectory.toPath().resolve("consolidation-client-pass.txt"),"PASS: "+checks+" checks; 18 native screenshots at GUI scales 2/3/4, actual Manager root/vault/chest/loot and Mobs import views; no overlapping buttons.\n");mc.stop();}}catch(Throwable error){com.ianblk.zianmobs.ZianMobs.LOGGER.error("CONSOLIDATION_CLIENT_SMOKE_FAILED",error);try{Files.writeString(mc.gameDirectory.toPath().resolve("consolidation-client-failed.txt"),error.toString());}catch(Exception ignored){}mc.stop();}}
 private static void open(Minecraft mc)throws Exception{mc.options.guiScale().set(2+stage/6);mc.resizeDisplay();String type=switch(stage%6){case 0->"root";case 1,2->"vault";case 3->"chests";case 4->"loot";default->"import";};Path root=Path.of(System.getenv("ZIAN_CONSOLIDATION_FIXTURES"));var data=JsonParser.parseString(Files.readString(root.resolve(type.equals("import")?"mobs-import.json":"manager-"+type+".json"))).getAsJsonObject();Screen screen=type.equals("import")?new MobsScreen(data):(Screen)Class.forName("com.ianblk.zianmanager.client."+(type.equals("loot")?"LootEditorScreen":"ManagerScreen")).getConstructor(JsonObject.class).newInstance(data);mc.setScreen(screen);
  if(stage%6==1){var tab=screen.children().stream().filter(c->c instanceof Button button&&button.getMessage().getString().equals("Ajustes")).map(c->(Button)c).findFirst().orElseThrow();if(tab.active){var fit=ResponsiveLayout.fit(mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),600,360);require(screen.mouseClicked(fit.x()+(tab.getX()+.2)*fit.scale(),fit.y()+(tab.getY()+.2)*fit.scale(),0),"vault retained tab can return to settings");}}
  if(stage%6==2){var b=screen.children().stream().filter(c->c instanceof Button button&&button.getMessage().getString().equals("Mi espera")).map(c->(Button)c).findFirst().orElseThrow();var fit=ResponsiveLayout.fit(mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),600,360);require(screen.mouseClicked(fit.x()+(b.getX()+.2)*fit.scale(),fit.y()+(b.getY()+.2)*fit.scale(),0),"vault tab edge click");}
  var buttons=screen.children().stream().filter(Button.class::isInstance).map(c->(Button)c).toList();for(int i=0;i<buttons.size();i++)for(int j=i+1;j<buttons.size();j++){var a=buttons.get(i);var b=buttons.get(j);require(!(a.getX()<b.getX()+b.getWidth()&&a.getX()+a.getWidth()>b.getX()&&a.getY()<b.getY()+b.getHeight()&&a.getY()+a.getHeight()>b.getY()),"buttons overlap: "+a.getMessage().getString()+" / "+b.getMessage().getString());}
  if(type.equals("root")){require(buttons.stream().noneMatch(b->b.getMessage().getString().equals("Mobs y jefes")||b.getMessage().getString().equals("Zonas de dungeon")||b.getMessage().getString().equals("Tablas de recompensas")),"legacy categories absent");require(buttons.stream().anyMatch(b->b.getMessage().getString().equals("Bóvedas vanilla")),"vault menu visible");}
 }
}
